// Приводит апдейт MAX к одной плоской структуре независимо от того, пришёл он
// long polling-ом или вебхуком. Дальше вниз по сценарию идёт только эта форма.
//
// dedup_key — ключ идемпотентности. В webhook-режиме MAX повторяет доставку
// при таймауте, и без него бот отвечал бы дважды. Для сообщения это mid,
// для нажатия кнопки — callback_id.
const ONLY_DIALOGS = String($env.ONLY_DIALOGS ?? 'true') !== 'false';

// Кнопка request_contact присылает обычное сообщение с вложением contact,
// внутри которого vCard. Телефон достаём оттуда, чтобы форма заказа не
// требовала от пользователя набирать номер руками.
function phoneFromAttachments(atts) {
  for (const a of atts ?? []) {
    if (a.type !== 'contact') continue;
    const vcf = a.payload?.vcf_info ?? '';
    const m = vcf.match(/TEL[^:\r\n]*:\s*([+\d][\d\s()\-]{5,})/i);
    if (m) return m[1].replace(/[\s()\-]/g, '');
    const p = a.payload?.tam_info?.phone ?? a.payload?.phone;
    if (p) return String(p);
  }
  return null;
}

function geoFromAttachments(atts) {
  for (const a of atts ?? []) {
    if (a.type === 'location') {
      return { lat: a.payload?.latitude ?? a.latitude, lon: a.payload?.longitude ?? a.longitude };
    }
  }
  return null;
}

function normalize(u) {
  const msg = u.message ?? {};
  const rec = msg.recipient ?? {};
  const cb = u.callback ?? {};
  const sender = cb.user ?? msg.sender ?? u.user ?? {};

  // Групповые чаты отсекаются здесь. Боевой токен состоит в реальных чатах,
  // поэтому по умолчанию бот отвечает только в личке.
  if (ONLY_DIALOGS && rec.chat_type && rec.chat_type !== 'dialog') return null;
  if (sender.is_bot) return null;

  const base = {
    update_type: u.update_type,
    chat_id: rec.chat_id ?? null,
    chat_type: rec.chat_type ?? null,
    user_id: rec.user_id ?? sender.user_id ?? null,
    name: sender.first_name ?? sender.name ?? 'друг',
    username: sender.username ?? null,
    raw: u,
  };

  if (u.update_type === 'message_created') {
    const atts = msg.body?.attachments;
    return { ...base, kind: 'message', text: (msg.body?.text ?? '').trim(),
             payload: null, callback_id: null,
             contact_phone: phoneFromAttachments(atts),
             geo: geoFromAttachments(atts),
             dedup_key: 'msg:' + (msg.body?.mid ?? `${base.user_id}:${u.timestamp}`) };
  }
  if (u.update_type === 'message_callback') {
    return { ...base, kind: 'callback', text: '', payload: cb.payload ?? '',
             callback_id: cb.callback_id ?? null, contact_phone: null, geo: null,
             dedup_key: 'cb:' + (cb.callback_id ?? `${base.user_id}:${u.timestamp}`) };
  }
  if (u.update_type === 'bot_started') {
    // Открытие диалога трактуем как /start.
    return { ...base, kind: 'message', text: '/start', payload: null, callback_id: null,
             contact_phone: null, geo: null,
             dedup_key: 'start:' + `${base.user_id}:${u.timestamp}` };
  }
  return null;
}

// Вход: ответ GET /updates.
const res = $input.first().json ?? {};
return (res.updates ?? []).map(normalize).filter(Boolean).map((json) => ({ json }));
